// Original text workshops. Inspector lenses are teaching commentary, never script quotations.
const C='https://www.gutenberg.org/files/46/46-h/46-h.htm';
const I='https://www.concordtheatricals.com/p/12689/an-inspector-calls';
const W='https://www.nationalarchives.gov.uk/help-with-your-research/research-guides/poverty-poor-laws/';
const make=d=>{
 const protectedText=d.topic==='inspector',topic=d.topic||'carol',id=`lit.${topic}.${d.key}`;
 const items=(stage,rows)=>rows.map(([prompt,correct,a,b,why,concept],i)=>{const answer=(i+d.key.length)%3,options=[a,b];options.splice(answer,0,correct);return{id:`${id}.${stage}.${i+1}`,prompt,options,answer,why,concept:`${id}.${concept}`};});
 return{id,topicId:`english-literature.${protectedText?'inspector-calls':'christmas-carol'}`,title:d.title,scope:d.scope,minutes:d.minutes||30,refs:[protectedText?'3.2.1':'3.1.2','3.3'],author:protectedText?'J.B. Priestley':'Charles Dickens',rights:protectedText?'protected_summary_only':'public_domain',textType:protectedText?'play':'prose',textTitle:protectedText?'An Inspector Calls':'A Christmas Carol',readingURL:protectedText?null:C,checked:'29 October 2026',sources:d.sources||[protectedText?I:C],sourceNote:protectedText?'Original teaching descriptions and interpretive lenses, not quotations or reproduced stage directions from the protected play. Read the assigned act in an authorised copy for exact words and full context. No production image, dialogue passage or invented quotation is supplied. Interpretations require evidence and can differ.':'Short passages from Dickens’s underlying public-domain text; original teaching analysis. Read the complete linked stave and novella. Quotation punctuation is typographically normalised; interpretations are possibilities to test, not fixed answers for every reader.',contextReading:(d.sources||[protectedText?I:C]).map((url,i)=>({url,label:url===C?'A Christmas Carol · complete text':url===I?'An Inspector Calls · publisher and authorised editions':url===W?'National Archives · poor law history':`Context source ${i+1}`})),cards:d.cards,views:[{kind:'language',label:protectedText?'Dramatic lenses':'Evidence decisions',title:d.scope,content:d.quote,words:d.details,originalSummary:protectedText,readingRegion:true},{kind:'people',label:'Compare perspectives',title:'Whose view and whose knowledge?',rows:d.people},{kind:'timeline',label:'Develop the argument',title:'Trace the reasoning',events:d.movement}],tasks:[[d.challenge[0],d.challenge.slice(1,4),0,d.challenge[4],d.challenge[5]]],practice:items('practice',d.practice),check:items('check',d.check),writing:d.writing,rubric:d.rubric,...(d.extra||{})};
};
export const batch11=[
make({key:'workshop-03',title:'Stave 3 social contrasts reading workshop',scope:'Stave 3 · abundance, scarcity and affection',quote:'They were not a handsome family; they were not well dressed; their shoes were far from being water-proof; their clothes were scanty;',
cards:[['Read lack beside celebration','Read the Cratchit meal alongside the earlier descriptions of festive shops and food. The narrator lists material deficiencies even within an affectionate family scene. A response that calls the family simply happy misses the insecure shoes and clothes; a response that sees only deprivation misses the relationships the narrative also values.'],['Explain the contrast rather than naming it','Repeated negatives accumulate what the family lacks. The nearby celebration makes the contrast sharper: dignity and enjoyment can exist without adequate resources. Compare a precise detail from each part of the stave and explain what the relation asks a reader to notice about the distribution of comfort.'],['Qualify the social argument','Affection does not make poverty harmless, and poverty does not remove the family’s individuality. A strong argument can value their relationships while recognising material danger, especially around Tiny Tim. Do not claim that the scene proves every poor household is identical or that cheerfulness removes an employer’s responsibility.']],details:[['not well dressed','The narrator explicitly records material shortage.'],['far from being water-proof','Ordinary protection from weather is insecure.'],['scanty','A short evaluative word keeps insufficiency visible.']],people:[['Narrator','Places material lack within a warm family scene.'],['Cratchits','Celebrate while living with insecure resources.'],['Scrooge','Witnesses lives previously kept outside his attention.']],movement:[['Compare','Recall the stave’s displays of abundance.'],['Notice','Identify the specific shortages in the family scene.'],['Relate','Explain how warmth and lack coexist.'],['Judge','Qualify the claim about social responsibility.']],challenge:['Which reading accounts for both kinds of evidence?','Family affection has value while material deprivation remains harmful.','Their celebration proves that inadequate resources never matter.','Their lack of wealth means they have no individual voices.','The scene allows relational richness and material insecurity to coexist.','Do not let one part of the contrast cancel the other.'],practice:[['What do the repeated negatives accumulate?','Specific things the family lacks.','Proof that the narrator dislikes every family member.','An exact household income calculation.','The pattern keeps material shortcomings in view.','methods'],['Why compare the shops with the meal?','The relation makes differences in comfort and resources visible.','It proves every household can buy everything displayed.','It replaces the need to read the family scene.','Contrast needs a relation between selected details.','contrast'],['Which inference should be resisted?','Celebrating means poverty has no damaging consequences.','The family experiences affection.','The narrator describes inadequate clothing.','Warmth does not remove material vulnerability.','limits']],check:[['What does the clothing description establish?','Material protection is inadequate despite the celebration.','The family possesses unlimited resources.','The scene is only a catalogue of fashionable purchases.','Literal shortages matter to a social reading.','meaning'],['How does scanty contribute?','It compresses a judgment of insufficiency into the description.','It guarantees that no reader can feel sympathy.','It provides a precise medical diagnosis.','Explain the word’s evaluative role in context.','methods'],['Which statement is qualified?','The scene values affection without making deprivation harmless.','All poor families are necessarily identical.','Love automatically supplies food and medical care.','Distinguish moral value from material security.','interpretation'],['What would strengthen a social argument?','Relate the family’s shortages to abundance elsewhere in the stave.','List foods without explaining their distribution.','Ignore every detail that complicates the thesis.','Use a structural relation to develop the judgment.','argument']],writing:'How does Dickens present affection alongside material insecurity in Stave 3? Compare the Cratchit scene with a display of abundance elsewhere and explain why the contrast matters.',rubric:['Analyse precise details of material lack and family affection together.','Explain a structural contrast with another moment in the stave.','Qualify the social judgment without treating poverty as harmless or families as identical.']}),
make({key:'workshop-04',title:'Stave 4 uncertainty and suspense workshop',scope:'Stave 4 · questions, silence and possible futures',quote:'Are these the shadows of the things that Will be, or are they shadows of things that May be, only?',
cards:[['Keep the question separate from an answer','Scrooge asks whether the scenes show an unavoidable future or a possible one. The Spirit continues to point rather than offering the verbal assurance he seeks. The question reveals his urgent hope; it does not by itself confirm either a fixed destiny or a guarantee that he is already safe.'],['Analyse how uncertainty is maintained','Will and May set different degrees of certainty against each other. The silence makes Scrooge and the reader work without immediate explanation, while the approach to the grave gives the uncertainty personal stakes. Explain how a question and withheld reply shape suspense rather than treating suspense as a label for any frightening object.'],['Connect possibility with the demand for action','Read Scrooge’s following argument that changed conduct could change an outcome. He seeks room to act differently, but the scene does not erase what the visions expose about his current course. A qualified interpretation links uncertainty with responsibility instead of replacing it with a simple claim that nothing matters.']],details:[['Will','The modal projects an outcome as certain.'],['May','An alternative leaves room for possibility.'],['shadows','The images represent a future whose status Scrooge questions.']],people:[['Scrooge','Seeks reassurance and a chance to act differently.'],['Spirit','Points without confirming the desired answer in speech.'],['Reader','Follows a question whose stakes become personal.']],movement:[['Witness','Read the scenes of consequences.'],['Ask','Distinguish certainty from possibility.'],['Wait','Notice the withheld verbal assurance.'],['Respond','Connect the uncertainty with a proposal to change conduct.']],challenge:['What can be concluded from Scrooge’s question alone?','He hopes the future can change, but has not received the assurance he seeks.','The Spirit has explicitly promised complete safety.','Scrooge has no desire to change any conduct.','A character’s request is not the same thing as confirmation.','Identify who asks and whether a verbal answer is actually given.'],practice:[['What does the Will/May contrast explore?','Different degrees of certainty about the future.','Two names for identical guaranteed outcomes.','The exact calendar date of every vision.','Modal wording makes the question about possibility.','methods'],['How does the Spirit’s silence contribute?','It withholds assurance while Scrooge confronts the stakes.','It states aloud that every event is fixed.','It proves the reader already knows all answers.','Suspense can grow through information not supplied.','suspense'],['Why read the following argument about courses?','It links possible change with changed conduct.','It makes every earlier choice irrelevant.','It proves Scrooge has already completed reform.','The proposal gives ethical force to the uncertainty.','agency']],check:[['Whose position does the displayed question reveal?','Scrooge’s uncertainty and desire for an alternative future.','The narrator’s guaranteed promise of immediate safety.','The Spirit’s spoken account of every later event.','Keep a speaker’s hope distinct from confirmed information.','meaning'],['What is a structural source of suspense?','A consequential question is followed by withheld verbal assurance.','Every uncertainty is immediately explained in detail.','The question has no relation to the grave.','Information and sequence shape the reader’s anticipation.','structure'],['Which claim exceeds the passage?','The question itself proves the future is already safely changed.','Scrooge distinguishes Will from May.','The Spirit continues to point.','A request for reassurance cannot stand as its own fulfilment.','limits'],['How can this moment develop a responsibility argument?','Possible alternatives make changed conduct urgent.','Uncertainty proves actions never have consequences.','Silence makes every moral question meaningless.','Connect the imagined future with the conduct being challenged.','argument']],writing:'How does Dickens use questions and silence to make Scrooge’s possible future urgent? Analyse the modal contrast and connect the uncertainty with the responsibility to change.',rubric:['Distinguish Scrooge’s question from information actually confirmed.','Analyse modal wording and the sequence of withheld assurance.','Connect suspense with conduct while qualifying claims about certainty.']}),
make({key:'workshop-05',title:'Stave 5 comic resolution and structural echoes',scope:'Stave 5 · release and evidence of reform',quote:'I am as light as a feather, I am as happy as an angel, I am as merry as a schoolboy.',
cards:[['Read the comic body','Scrooge struggles with his clothes, laughs and describes himself through a rush of comparisons. The energy offers release after the grave scene and disrupts the opening portrait of hard self-containment. Attend to the comic physical action as well as the words; the scene presents a changed manner, not just a declaration of an abstract lesson.'],['Trace an echo across the novella','The lightness contrasts with earlier heaviness and the burden of Marley’s chain. The relation can suggest a release from a constricted way of living. It does not mean the feather is a literal object onstage or that every light image always has one moral value. Explain the comparison in its particular position after the visions.'],['Test joy against subsequent action','The emotional release needs the later gift, visit and improved treatment of Bob to support a claim about reform. Happiness alone would not prove a lasting ethical change. Use the narrator’s account of continuing conduct to develop the argument while acknowledging that the conclusion is a constructed resolution rather than a complete policy programme.']],details:[['light as a feather','A weight comparison presents felt release.'],['happy as an angel','The sequence intensifies an expression of joy.'],['merry as a schoolboy','A return to youth helps present renewed possibility.']],people:[['Scrooge','Expresses joy and then acts towards others.'],['Narrator','Connects comic energy with a concluding account of conduct.'],['Bob','Experiences material consequences of Scrooge’s later decisions.']],movement:[['Release','Read the comic response after the grave.'],['Echo','Compare lightness with earlier burdens.'],['Act','Follow giving, visiting and changed employment conduct.'],['Evaluate','Use more than emotion to judge reform.']],challenge:['Which evidence best tests whether joy becomes reform?','The later treatment of other people, including Bob.','The number of similes alone proves every problem is solved.','A single laugh cancels the need for any subsequent action.','An ethical interpretation needs conduct as well as feeling.','Follow what Scrooge does after describing his happiness.'],practice:[['Why consider the comic dressing scene?','Physical disorder helps present release from earlier rigidity.','It supplies a precise costume plan for every production.','It proves the narrator has stopped shaping the story.','Narrative action can contribute to the presentation of change.','comedy'],['What makes the lightness comparison structural?','It can be related to earlier images of burden and confinement.','Every image of lightness has the same meaning everywhere.','A feather literally removes Marley’s chain.','An echo needs an explained relation across moments.','echo'],['What would be an overclaim?','Joy by itself guarantees lasting ethical reform.','The later wage decision matters to Bob.','The ending revisits earlier relations.','Distinguish an emotional response from sustained conduct.','limits']],check:[['What does the simile sequence present immediately?','An energetic expression of Scrooge’s felt renewal.','An official report on a national welfare system.','A literal transformation into a bird.','Read figurative descriptions as a presentation of feeling.','meaning'],['Which comparison develops a whole-text reading?','Lightness at the ending can be contrasted with earlier burdens.','Only the last page is relevant to structural analysis.','All earlier imagery must be ignored once the tone changes.','The ending can revise the significance of an earlier image.','structure'],['Which later evidence supports reform?','Changed treatment of Bob and continuing care for others.','Only an increase in the length of Scrooge’s speeches.','A claim that money is now unnecessary for everyone.','Material and relational acts give the joy ethical consequences.','evidence'],['Which judgment is qualified?','Comic release contributes to a resolution supported by later conduct.','One laugh proves every social problem permanently solved.','A cheerful tone makes previous harm irrelevant.','A literary resolution can be meaningful without being total.','argument']],writing:'How does comic release at the start of Stave 5 become evidence of a wider transformation? Connect a precise comparison to an earlier image and test it against later conduct.',rubric:['Analyse comic action and a precise simile in their immediate position.','Explain a structural echo rather than merely naming a repeated idea.','Use later conduct to qualify a judgment about sustained reform.']}),
make({key:'workshop-06',title:'Scrooge evidence-led character argument',scope:'Whole novella · testing a developmental thesis',quote:'secret, and self-contained, and solitary as an oyster.',
cards:[['State a thesis that can develop','An opening claim might argue that Scrooge’s isolation is challenged as the narrative exposes the human consequences of his separation. This gives the essay a direction through the novella. A label such as greedy is relevant but insufficient: it needs an account of how relationships, knowledge and conduct change.'],['Use awkward evidence to refine the claim','The childhood scene introduces vulnerability, while the later refusal of responsibility remains harmful. A lonely past can complicate a judgment without automatically excusing adult conduct. Test a fixed-villain thesis against memory and a simple-victim thesis against decisions that affect Bob and the charity collectors.'],['Build a reasoned ending','Connect the opening enclosure to later openness through particular words and actions. The final account of friendship and employer conduct provides more support than a general claim that Scrooge is nice now. Explain the relation between knowing differently and acting differently, and avoid treating a character’s ending as proof that every social problem disappears.']],details:[['secret','The description concerns concealment as well as solitude.'],['self-contained','The image of enclosure helps frame a relational problem.'],['solitary','Separation becomes a point to test against later relationships.']],people:[['Opening narrator','Constructs a severe initial portrait.'],['Remembered child','Complicates a fixed judgment through vulnerability.'],['Later Scrooge','Provides conduct against which to test a change claim.']],movement:[['Propose','Give the argument a developmental direction.'],['Test','Find evidence that complicates an initial label.'],['Connect','Analyse a relation between early and late moments.'],['Judge','Explain what the ending supports and what it cannot prove.']],challenge:['Which thesis is open to a sustained evidence test?','Isolation is challenged through new knowledge of others and altered conduct.','Scrooge is simply one label that never needs qualification.','One childhood memory makes all adult decisions morally right.','A developmental claim can account for change and complication.','Ask whether the claim explains more than a fixed adjective.'],practice:[['Why include childhood vulnerability?','It complicates a judgment without automatically excusing later harm.','It proves all later choices are inevitable and justified.','It replaces the need for adult evidence.','Explanation and moral justification remain different claims.','qualification'],['What should an ending paragraph use?','Specific later relationships and conduct that test the opening thesis.','Only a new adjective without evidence.','An unrelated plot from another novel.','A conclusion should follow from the argued development.','argument'],['Which comparison is analytical?','Explain how later openness revises the opening enclosure.','List the first and last pages without a relation.','Assume repeated words always mean identical things.','A relation gives the selected moments argumentative purpose.','structure']],check:[['What does a developmental thesis need?','An account of how knowledge, relationships or conduct alter.','Only a fixed label repeated in every paragraph.','A promise that contrary evidence will be ignored.','An argument should have a direction the text can test.','meaning'],['Which claim is too simple?','A lonely childhood automatically excuses every later decision.','The childhood scene can encourage sympathy.','Later conduct matters to judging change.','A complex character can be vulnerable and responsible.','limits'],['How should counter-evidence be used?','Refine the thesis so it can explain an awkward moment.','Delete it from the story without explanation.','Replace it with invented words that agree.','A tested claim responds to what challenges it.','evaluation'],['What supports the final judgment?','A reasoned relation between early presentation and later conduct.','An unsupported assertion that every problem is solved.','A count of quotations without interpretation.','Evidence must do work within the line of reasoning.','argument']],writing:'Develop an argument about Scrooge’s isolation and change. Use an opening detail, a complicating memory and a later action, explaining how each tests your thesis.',rubric:['Sustain a developmental claim rather than repeat a fixed character label.','Use accurate early, middle and late evidence with close analysis.','Address a complicating moment and qualify the final judgment.']}),
make({key:'workshop-07',title:'Bob Cratchit work and dignity workshop',scope:'Staves 1 and 3 · labour, power and family voice',quote:'the clerk’s fire was so very much smaller that it looked like one coal.',
cards:[['Read the workplace through control','Scrooge controls the coal-box and threatens the clerk’s employment when he seeks more fuel. The comparison of fires makes inequality tangible. Bob’s limited response does not establish free consent to the conditions: the power to threaten a livelihood shapes what a worker can safely request or say.'],['Distinguish comparison from literal setting','The narrator describes the clerk’s working space as a cell and a tank. These comparisons can suggest restriction without making the counting-house literally a prison or aquarium. Explain how the spatial language and control of warmth work together, rather than claiming a figurative description proves a legal fact.'],['Preserve dignity without idealising deprivation','At home Bob participates in affectionate relationships and values Tiny Tim. Those voices broaden him beyond the workplace role. Dignity does not mean the cold or low resources are acceptable. Connect the family scene with the ending’s material improvement to argue why respect and practical change need to belong together.']],details:[['clerk’s','The role identifies an employment relationship.'],['so very much smaller','Comparison makes unequal access emphatic.'],['one coal','An extreme visual measure makes scarcity immediate.']],people:[['Scrooge','Controls resources and threatens employment.'],['Bob','Works within unequal power and has relationships beyond work.'],['Narrator','Uses spatial and heat comparisons to make conditions visible.']],movement:[['Locate','Identify control over warmth and livelihood.'],['Analyse','Explain the comparison of resources.'],['Broaden','Read Bob’s voice within his family.'],['Connect','Relate dignity to practical improvement at the ending.']],challenge:['Which reading respects both power and dignity?','Bob’s limited protest does not prove the conditions are fair or freely accepted.','Silence proves he wants to be cold.','Family affection removes an employer’s responsibility.','A worker’s choices occur within material constraints.','Distinguish limited room to act from enthusiastic consent.'],practice:[['What does the fire comparison expose?','Unequal access to basic warmth.','An exact technical measurement of the building.','Proof that Bob owns the coal-box.','The description makes a power relation concrete.','methods'],['How should the cell description be read?','As a spatial comparison suggesting restriction.','As proof of a criminal prison sentence.','As a literal aquarium containing the clerk.','Figurative setting can carry meaning without literal identity.','imagery'],['Why read the family scene too?','It gives Bob relationships and dignity beyond an employment role.','It proves resources never affect his family.','It makes the workplace scene false.','A broad character account includes more than one social position.','character']],check:[['Who controls the fuel in the opening workplace?','Scrooge controls access to the coal.','Bob has unlimited independent access.','Tiny Tim allocates every worker’s salary.','Control of a basic resource matters to the scene.','meaning'],['What makes the comparison evaluative?','The extreme difference draws attention to unequal conditions.','It provides a complete national wage survey.','It confirms that cold is always harmless.','A selected detail can invite judgment about a relation.','methods'],['Which inference is unjustified?','Limited protest proves free approval of the working conditions.','Employment threats constrain Bob’s choices.','Family life broadens his presentation.','Power can affect what a person can safely say.','limits'],['Which whole-text connection develops the argument?','Link early fuel control with later improved treatment and pay.','Mention the ending without explaining any change.','Ignore material conditions when discussing dignity.','Respect becomes more convincing when conduct changes.','structure']],writing:'How does Dickens present Bob’s dignity within unequal working conditions? Analyse the fire comparison, a family moment and a relevant change in the ending.',rubric:['Explain control of resources without treating limited protest as consent.','Analyse figurative setting or comparison with literal accuracy.','Connect dignity and relationships with the need for practical improvement.']}),
make({key:'workshop-08',title:'Fred and the counterargument to isolation',scope:'Staves 1 and 3 · shared journeys and invitations',quote:'fellow-passengers to the grave, and not another race of creatures bound on other journeys.',
cards:[['Locate the speech within an argument','Fred answers Scrooge’s dismissal of Christmas by describing a time of openness and shared humanity. His speech is a character’s persuasive position, not a neutral survey proving that everyone behaves generously. Read the exchange and the repeated invitation to see what his argument attempts to change.'],['Explain the shared-journey comparison','Fellow-passengers makes social difference part of a common mortal journey. The contrast with another race of creatures challenges a habit of imagining poorer people as fundamentally separate. Analyse that relation rather than assuming the metaphor means everyone has identical money, opportunities or power.'],['Test the counterargument through conduct','Fred’s invitations offer a practical alternative to withdrawal even after rejection. The later visit gives the opening dispute a structural answer, but the initial speech does not convert Scrooge at once. A qualified reading connects persistence, shared humanity and changed participation without claiming that an invitation solves every inequality.']],details:[['fellow-passengers','A shared journey challenges exclusion.'],['to the grave','Common mortality gives the comparison a serious basis.'],['not another race','The contrast resists treating others as a separate kind of being.']],people:[['Fred','Advocates connection and continues to invite.'],['Scrooge','Initially rejects an alternative to withdrawal.'],['Reader','Can compare the invitation with the later visit.']],movement:[['Argue','Locate the speech as a response to dismissal.'],['Compare','Explain the shared-journey metaphor.'],['Persist','Follow the repeated offer of company.'],['Revisit','Connect early refusal with later participation.']],challenge:['What does the shared journey imply?','People share mortality without necessarily sharing equal resources or power.','Everyone already has identical wealth and opportunity.','The speech immediately ends every conflict.','Common humanity is not an assertion of identical conditions.','Explain the basis of the comparison rather than extending it beyond the speech.'],practice:[['Why identify Fred as speaker?','The words function as a persuasive response in a relationship.','They are a neutral official census of Christmas behaviour.','The narrator has no role in framing the exchange.','Speaker and purpose shape how an argument operates.','speaker'],['What does the metaphor challenge?','A habit of treating poorer people as fundamentally separate.','The existence of every social difference.','The fact that people have different names.','Interpret a comparison through the distinction it makes.','methods'],['Why trace the invitations?','They turn the alternative to isolation into a repeated practical offer.','They prove Scrooge accepts at the first request.','They remove all material duties towards workers.','Conduct can carry an argument beyond its wording.','structure']],check:[['What is Fred doing in the opening exchange?','Defending a form of shared social openness.','Giving a guaranteed account of every person’s conduct.','Demanding that Bob lose his job.','Read a character’s argument in its immediate dispute.','meaning'],['What gives to the grave significance?','It grounds the shared journey in common mortality.','It predicts an exact date of death for every guest.','It proves that all social conditions are equal.','The image offers a basis for human connection.','methods'],['Which reading overstates the effect?','The speech converts Scrooge immediately and solves every inequality.','Repeated invitations resist withdrawal.','The later visit can answer an earlier refusal.','A persuasive alternative can matter without immediate success.','limits'],['How can the ending develop this argument?','Later participation revises the meaning of the opening refusal.','Only the quantity of food at dinner matters.','The invitation becomes irrelevant once a ghost appears.','Use an explained relation across the novella.','argument']],writing:'How does Fred offer a counterargument to isolation? Analyse the shared-journey comparison and trace the relation between invitation, refusal and later participation.',rubric:['Locate the speech as a character’s persuasive response rather than a neutral survey.','Explain the metaphor without claiming equal material circumstances.','Connect repeated invitations with later conduct and qualify their effect.']}),
make({key:'workshop-09',title:'Mrs Cratchit and competing judgments workshop',scope:'Stave 3 · the toast and disagreement',quote:'“The Founder of the Feast indeed!” cried Mrs. Cratchit, reddening.',
cards:[['Read the exchange rather than one isolated line','Bob proposes a toast to Scrooge; Mrs Cratchit answers with anger and a wish to confront him. Her reaction prevents the household from becoming a single voice of grateful approval. Read Bob’s response and the eventual toast as a negotiation within the family, not proof that her earlier criticism disappears.'],['Explain how repetition changes function','Mrs Cratchit repeats the designation of Scrooge as founder, but indeed turns it into a challenge. Tone is inferred from the surrounding reaction and speech, not from the repeated words alone. The comic offer of a piece of her mind exposes a conflict between ceremonial gratitude and experience of inadequate provision.'],['Compare judgments without ranking people lazily','Bob appeals to Christmas and the children, while Mrs Cratchit voices a legitimate grievance. An argument can consider affection, tact and dependence without dismissing her as merely unkind or Bob as simply foolish. Support a judgment about what each position reveals and acknowledge why a household under pressure may contain disagreement.']],details:[['Founder of the Feast','A ceremonial title is repeated in challenge.'],['indeed','The response questions rather than simply endorses the title.'],['reddening','A reported physical reaction supports an inference of anger.']],people:[['Bob','Proposes a toast and appeals to the occasion.'],['Mrs Cratchit','Challenges gratitude towards an employer she criticises.'],['Children','Hear the dispute within the shared celebration.']],movement:[['Propose','Read the toast in context.'],['Challenge','Notice how the repeated title changes tone.'],['Negotiate','Follow the appeal to the occasion and children.'],['Judge','Preserve disagreement within a loving household.']],challenge:['Which reading keeps both voices in view?','The family’s celebration includes a disagreement about gratitude and grievance.','Everyone expresses identical approval of Scrooge throughout.','Mrs Cratchit’s criticism proves she has no affection for her family.','A shared occasion does not erase different ethical judgments.','Read the response as a challenge within the exchange.'],practice:[['What happens to the repeated title?','Its approving function is challenged by the response.','It becomes a neutral legal definition of Scrooge.','It proves Bob and Mrs Cratchit use identical tones.','Repeated words can acquire different purposes through context.','methods'],['What supports the inference of anger?','The reported reddening and surrounding criticism.','Only the fact that the line contains a capital letter.','An invented stage direction from a modern film.','Use the available narrative and speech evidence.','evidence'],['Why avoid calling the household unanimously grateful?','Mrs Cratchit voices a grievance within the celebration.','There is no toast or disagreement in the scene.','Only Scrooge is allowed to speak in Stave 3.','A family’s shared affection does not mean a single opinion.','voices']],check:[['What does Mrs Cratchit’s reply do?','Challenges the account of Scrooge as benefactor.','Withdraws every criticism before she speaks.','Introduces a new ghost into the meal.','The reply contests the meaning of the toast.','meaning'],['Why does indeed matter in context?','It helps turn repetition into a sceptical response.','It always signals complete agreement in every sentence.','It supplies a precise financial calculation.','Small words acquire force through the surrounding exchange.','methods'],['Which judgment is too reductive?','Mrs Cratchit is merely cruel and has no reason to object.','Her criticism makes inadequate provision visible.','Bob values the occasion and children.','Evaluate a grievance instead of replacing it with a label.','interpretation'],['What makes a comparison of the couple analytical?','Explain the different pressures and purposes behind their responses.','Rank them without using the exchange.','Assume affection requires identical opinions.','Contrasting positions need an account of situation and conduct.','argument']],writing:'How does the toast exchange complicate the presentation of gratitude? Analyse Mrs Cratchit’s response alongside Bob’s and explain what their disagreement reveals.',rubric:['Analyse a repeated phrase in its changing conversational function.','Use precise evidence for tone instead of assuming a universal word effect.','Compare the judgments fairly without erasing affection or material grievance.']}),
make({key:'workshop-10',title:'Poverty and welfare context linked to passages',scope:'Stave 1 · institutional answers to human need',sources:[C,W,'https://www.parliament.uk/about/living-heritage/transformingsociety/livinglearning/19thcentury/overview/poorlaw/'],quote:'“And the Union workhouses?” demanded Scrooge. “Are they still in operation?”',
cards:[['Identify the particular institutional reference','Scrooge answers an appeal for help by asking about prisons and Union workhouses. Following the 1834 reform, parishes in England and Wales were grouped into poor law unions administering relief and workhouses. This makes his reply socially recognisable; it does not mean every form of poor relief or every institution was identical.'],['Make context explain a rhetorical choice','The appeal concerns immediate human need, while Scrooge redirects attention to institutions already operating. His questions can be read as a way to delegate responsibility away from himself. Connect the historical reference to that function rather than inserting an unrelated account of Victorian life between quotations.'],['Keep the interpretation within its evidence','The novella challenges a narrow response to need through scenes of particular lives and changed conduct. It does not set out a complete legislative replacement for the poor laws. Avoid claiming that every contemporary reader necessarily agreed, or that the existence of an institution proves everyone in need was adequately protected.']],details:[['Union workhouses','The reference belongs to a recognisable relief system.'],['demanded','The reporting verb gives the question force.'],['still in operation','The focus shifts towards institutions being available rather than this person giving help.']],people:[['Collectors','Appeal for provision for people in need.'],['Scrooge','Redirects the appeal towards existing institutions.'],['Contextual reader','Relates a historical reference to its function in the exchange.']],movement:[['Identify','Locate the institutional reference.'],['Verify','Check the 1834 reform without adding unsupported generalisations.'],['Analyse','Explain how the reply redirects responsibility.'],['Qualify','Distinguish a social challenge from a full policy programme.']],challenge:['Which contextual sentence serves the analysis?','The poor law reference helps Scrooge redirect an appeal towards institutions instead of personal help.','An unrelated Victorian invention automatically explains the whole speech.','Every person needing relief was already fully protected.','Context should illuminate the function of a particular textual choice.','Relate the historical fact to the answer Scrooge gives.'],practice:[['What does the 1834 context clarify?','Why Union workhouses are a recognisable institutional reference.','A guarantee that every institution treats people identically.','The exact personal income of each collector.','Use the verified fact at the scale the evidence supports.','context'],['How can the questions function?','They can redirect a personal appeal towards existing institutions.','They necessarily promise a generous donation.','They show Scrooge has not heard any request.','Explain what the speech does within the exchange.','methods'],['Which claim goes beyond the novella?','It provides a complete detailed legislative replacement for the poor laws.','It challenges an inadequate response to need.','Particular lives matter to its social argument.','A literary social criticism is not a full statutory programme.','limits']],check:[['What has prompted the institutional questions?','An appeal to help people in need.','A request to name the Ghost of Christmas Past.','An official report of Scrooge’s final wage increase.','Locate the speech within its immediate exchange.','meaning'],['What makes context analytical?','A verified fact helps explain the reply’s function.','Background facts replace all attention to language.','A date alone guarantees an interpretation.','Historical knowledge should serve a textual claim.','context'],['Which inference is unsafe?','An operating institution proves every person’s needs are adequately met.','Scrooge refers to workhouses.','The collectors ask for help.','Availability does not establish adequacy or equal experience.','evaluation'],['Which final judgment stays proportionate?','The narrative challenges delegated responsibility without specifying a complete policy system.','Every reader in 1843 necessarily agreed with every implication.','No social question can be explored through fiction.','Keep the argument meaningful and within its evidence.','argument']],writing:'How does Scrooge’s institutional reply present a limited response to poverty? Use one verified contextual fact and close analysis, then qualify what the novella does and does not propose.',rubric:['Use a verified poor law fact at the appropriate historical and geographic scale.','Explain how the institutional questions function within a particular appeal.','Qualify claims about relief, readers and the novella’s social proposals.']}),
make({key:'workshop-11',title:'Christmas and social responsibility context workshop',scope:'Staves 1 and 5 · business beyond trade',quote:'Mankind was my business. The common welfare was my business;',
cards:[['Hear the challenge within the word business','Scrooge describes Marley as a good man of business; Marley answers by widening what business should have meant. The repeated word changes from commercial dealings towards human obligations. Analyse that dispute in meaning rather than simply stating that money is bad or that all trade is condemned.'],['Relate seasonal feeling to ongoing conduct','Christmas brings encounters and a language of generosity, but the ending extends the question beyond one festive meal. Scrooge’s improved treatment of Bob and continuing friendship give social feeling practical consequences. A response should not reduce responsibility to a temporary mood or claim the story demands that every reader celebrate identically.'],['Qualify the scale of the proposal','The contrast asks an individual to see obligations beyond commercial success. It can support a social argument about care while not amounting to a complete political or economic system. Use the narrative’s particular acts of giving and employment conduct to show what changes, and distinguish that evidence from a claim that all inequality is solved.']],details:[['Mankind','The scope expands beyond customers or accounts.'],['common welfare','Human well-being becomes a responsibility.'],['my business','Repetition contests the narrow commercial meaning.']],people:[['Scrooge before the challenge','Associates good business with commercial success.'],['Marley','Reinterprets duty through regret.'],['Later Scrooge','Acts towards people previously excluded from attention.']],movement:[['Narrow','Locate the commercial definition being offered.'],['Challenge','Read Marley’s widening of the term.'],['Connect','Follow practical changes in the ending.'],['Judge','Consider ongoing obligations beyond a seasonal mood.']],challenge:['Which claim follows the dispute over business?','Commercial success does not exhaust the obligations to other people.','Every form of work or trade is necessarily condemned.','One festive emotion proves every social problem solved.','The word is being widened, not simply removed.','Compare the two meanings of business in the exchange.'],practice:[['What method drives Marley’s reply?','Repetition redefines a familiar commercial word.','A literal balance sheet lists every expense.','A neutral announcement avoids all judgment.','The repeated term becomes a site of disagreement.','methods'],['Why consider the wage decision?','It gives social feeling a practical employment consequence.','It proves Bob’s early cold never mattered.','It replaces all need to consider ongoing conduct.','An act helps test whether responsibility extends beyond sentiment.','conduct'],['Which distinction keeps the claim accurate?','A social challenge is different from a complete economic programme.','Every ethical argument must specify a full legal code.','The novella gives exact rules for every society.','Interpret the scale and form of the work honestly.','limits']],check:[['What does common welfare add?','A concern with human well-being beyond trade.','An exact account of Marley’s shop profits.','Proof that the collectors require no help.','The reply widens the scope of obligation.','meaning'],['How does repetition work here?','The same word is disputed through a changed definition.','It necessarily means the speakers agree completely.','It removes the difference between trade and duty.','Context can change the function of repeated wording.','methods'],['What tests responsibility beyond a seasonal mood?','Continuing care and altered conduct towards others.','Only the number of festive decorations.','A claim that joy replaces material resources.','Use action over time to support an ethical judgment.','structure'],['Which argument is proportionate?','The story challenges narrow self-interest through particular acts of care.','The ending proves all inequality permanently eliminated.','No reader can question the proposed relations.','A social reading can be substantial without total claims.','argument']],writing:'How does Dickens widen the meaning of business into social responsibility? Analyse Marley’s repeated wording and connect it with practical conduct in the ending.',rubric:['Explain a disputed word through its contrasting meanings in the exchange.','Connect social feeling with particular material or relational acts.','Qualify the proposal without claiming a complete political system or universal solution.']}),
make({key:'workshop-12',title:'Narrative voice and recurring imagery workshop',scope:'Whole novella · asides, certainty and changing images',quote:'Mind! I don’t mean to say that I know, of my own knowledge, what there is particularly dead about a door-nail.',
cards:[['Distinguish narrative voice from biography','The narrator interrupts the opening death comparison with a playful aside. This is a constructed voice addressing a reader, not reliable evidence of every belief or personal habit of Dickens. Read how the interruption manages certainty and companionship before describing it only as an amusing digression.'],['Explain what the aside does','The conversational qualification temporarily questions a familiar phrase while the surrounding opening insists on Marley’s death. That combination can build a reader’s attention to how the tale is told. A qualification about an expression does not mean the narrator has withdrawn the essential premise that Marley is dead.'],['Trace imagery through its changing contexts','Cold, warmth, enclosure and light recur, but their meanings need to be established in each scene. Compare the cold workplace with a family fire or the ending’s energy, showing how conditions and relationships alter the image. An image map becomes an argument only when it explains differences rather than assigning one fixed meaning everywhere.']],details:[['Mind!','Direct address interrupts and draws the reader into the telling.'],['my own knowledge','A qualification makes the voice conversational and self-conscious.'],['door-nail','A familiar comparison is briefly examined without undoing the death premise.']],people:[['Narrator','Constructs a conversational relation with the reader.'],['Reader','Follows qualifications and emphatic assurances.'],['Biographical Dickens','Must not be inferred completely from a fictional voice.']],movement:[['Locate','Read the aside within the opening insistence.'],['Distinguish','Separate comment on a phrase from doubt about the event.'],['Compare','Follow an image into a different scene.'],['Argue','Explain how its function changes with context.']],challenge:['What does the aside question directly?','The familiar door-nail expression, not the basic premise of Marley’s death.','It announces that Marley never died.','It proves the narrator is a literal eyewitness to every later event.','The target of a qualification needs to be located precisely.','Read what is qualified alongside what the surrounding opening insists.'],practice:[['Why avoid equating narrator and author completely?','The telling voice is a constructed part of the novella.','Dickens has no relation to the book at all.','Every sentence is an unmediated personal diary entry.','Narrative presentation is not a complete biographical record.','voice'],['How can direct address work?','It can make a reader feel drawn into a conversational telling.','It guarantees an identical response in every reader.','It erases the narrator from the story.','Explain a possible relationship supported by the method.','methods'],['What makes recurring imagery analytical?','Explain how its function changes between particular contexts.','Give each image one permanent meaning without checking scenes.','Only count every occurrence of a word.','Recurrence and variation matter together.','imagery']],check:[['What remains an essential premise of the opening?','Marley is dead before the ghost story develops.','The aside guarantees Marley is still alive.','The narrator has withdrawn every statement.','A playful qualification has a particular target.','meaning'],['What does Mind! contribute?','It interrupts and directly engages the reader.','It supplies an official medical diagnosis.','It proves no narrator is present.','A brief address shapes the relation of teller and reader.','methods'],['Which biographical claim exceeds the evidence?','The fictional voice proves every private belief of Dickens.','The narrator comments on a familiar expression.','The aside is part of the telling.','Do not turn a constructed voice into complete biography.','limits'],['Which image comparison is useful?','Explain how warmth functions differently in a controlled workplace and a family scene.','Assign warmth an identical meaning in every context.','Count fireplaces instead of developing a claim.','A precise relation turns a motif into an argument.','argument']],writing:'How does Dickens make the telling voice distinctive? Analyse the opening aside, then connect the narrator’s selection of a recurring image with a wider argument about relationships.',rubric:['Locate the narrator’s qualification without undoing the opening premise.','Analyse direct address or conversational phrasing with a qualified effect.','Explain recurrence and variation while keeping narrative voice distinct from biography.']}),
make({key:'workshop-13',title:'Timed novel extract-to-whole assessment',scope:'Stave 2 preparation · fresh Stave 3 assessment',minutes:50,quote:'A solitary child, neglected by his friends, is left there still.',
cards:[['Prepare through a specific detail','The Ghost’s description of the schoolchild gives a practice route from a detail to an argument about vulnerability. Locate the speaker and scene before inferring an effect. The later assessment supplies a different passage about children and responsibility, so prepare a method of close reading rather than a paragraph to paste unchanged.'],['Connect without abandoning the passage','A novel extract-to-whole argument should analyse what the supplied passage presents and then develop that claim through relevant moments elsewhere. A remembered scene is useful only when its connection to the task is explained. Plot coverage or contextual facts cannot substitute for the reasoning between a detail and a judgment.'],['Plan, write and check independently','Aim for about 45 minutes including planning and editing; timing is advisory, not enforced. The fresh task hides teaching guidance and criteria until first submission. Your original response is preserved separately from revisions. This is original practice, not an official paper, and no essay mark follows from the selected-response checks.']],details:[['solitary','The description foregrounds isolation.'],['neglected','A relationship of failed care is implied.'],['still','The remembered situation is made present to its witness.']],people:[['Ghost of Christmas Past','Directs attention to a vulnerable child.'],['Scrooge','Recognises a remembered situation and responds.'],['Independent writer','Must adapt the method to a different supplied passage.']],movement:[['Locate','Read speaker, scene and immediate situation.'],['Analyse','Build a claim from a precise detail.'],['Connect','Develop that claim through relevant wider evidence.'],['Check','Review accuracy, relevance and sentence control.']],challenge:['Which preparation transfers to a fresh passage?','Practise adapting a method and selecting evidence for the actual question.','Paste a memorised schoolchild paragraph into every task.','Ignore the supplied language and only retell the ending.','Transfer depends on responding to this evidence and question.','Check whether the prepared idea actually serves the fresh task.'],practice:[['What should wider references do?','Develop a claim grounded in the supplied passage.','Replace close reading with unrelated plot coverage.','Prove every scene has identical meaning.','Whole-text evidence needs an explained argumentative relation.','structure'],['What is the suggested timing?','An advisory practice budget of 45 minutes, not an enforced examination timer.','An automatic guarantee of a GCSE grade.','A compulsory identical pace for every learner.','The workspace saves writing without policing time or resources.','conditions'],['What should final checking prioritise?','Task relevance, accurate references and controlled sentences.','Adding invented quotations to make the response longer.','Replacing every qualification with certainty.','Editing should improve accuracy and reasoning.','editing']],check:[['What makes a connection relevant?','It develops the passage-based argument about the actual question.','It comes from another stave but has no explained relation.','It replaces all attention to the passage.','A useful reference serves the line of reasoning.','meaning'],['What should a fresh passage change?','The writer’s selection and development of evidence.','Nothing, because every memorised paragraph fits every task.','The identity of the author without any evidence.','A new stimulus requires attentive reading and adaptation.','transfer'],['What is preserved after first submission?','The first response separately from later revisions.','An automatic official examiner mark.','Only the latest revision with every earlier word erased.','A preserved response supports honest later review.','assessment'],['Which edit improves evidence use?','Correct a misattribution and clarify its relevance to the claim.','Append an unrelated historical date for length.','Invent a convenient phrase in quotation marks.','An edit should strengthen the relation between evidence and argument.','editing']],writing:'Practise connecting the neglected schoolchild detail to a wider claim, then start the independent workspace and respond to its different passage.',rubric:['Sustain a relevant argument that addresses the actual question throughout.','Analyse the supplied passage closely and develop it through accurate wider evidence.','Use context where it explains a detail and maintain controlled, qualified expression.'],extra:{independentWriting:true,independentTaskType:'extract-to-whole',independentTaskLabel:'Original novel extract-to-whole practice, not an official exam paper.',independentIntro:'Aim for about 45 minutes including planning and checking. Timing is advisory, not enforced. Read the supplied passage and develop your own argument.',independentPrompt:'Starting with this passage, explore how Dickens presents responsibility towards vulnerable people. Write about this passage and how responsibility is presented elsewhere in A Christmas Carol.',independentExtractLabel:'A Christmas Carol · Stave 3 · Scrooge and the Ghost of Christmas Present',independentExtract:'“Spirit! are they yours?” Scrooge could say no more.\n\n“They are Man’s,” said the Spirit, looking down upon them. “And they cling to me, appealing from their fathers. This boy is Ignorance. This girl is Want. Beware them both, and all of their degree, but most of all beware this boy, for on his brow I see that written which is Doom, unless the writing be erased. Deny it!” cried the Spirit, stretching out its hand towards the city. “Slander those who tell it ye! Admit it for your factious purposes, and make it worse. And bide the end!”'}}),
make({key:'workshop-14',title:'Feedback-led novel redraft and delayed recall',scope:'Whole novella · review, revision and later retrieval',quote:'I will honour Christmas in my heart, and try to keep it all the year.',
cards:[['Diagnose an actual weakness','Bring your first novel assessment into this workshop if it is saved on this device, or work with an existing draft. Use the criteria and any real teacher feedback to identify one weakness. The app does not fabricate a mark or a comment. Choose a specific gap in claim, evidence, explanation or expression rather than deciding the essay is simply bad.'],['Make the change answer the diagnosis','If a paragraph says a promise proves complete reform, distinguish the promise to try from later evidence of conduct. Add or refine a relevant wider reference and explain why it changes the judgment. A substantive redraft strengthens reasoning; changing a few synonyms without addressing the gap is not the same thing.'],['Keep versions and return after an interval','Save the revised version and note the improvement you intended. The original first submission remains separate. Later, try to retrieve a relevant reference before reopening the source, then verify it. Review schedules missed knowledge concepts; immediate completion does not itself establish long-term retention or the quality of an independent essay.']],details:[['I will','The speaker makes a forward-looking commitment.'],['try','An intention is expressed without being a complete record of future conduct.'],['all the year','The proposed responsibility extends beyond one festival.']],people:[['First-response writer','Has a preserved attempt to examine honestly.'],['Reviewer','Uses actual writing, criteria and real feedback if available.'],['Revising writer','Changes reasoning and later tests retrieval.']],movement:[['Diagnose','Identify a gap in the actual argument.'],['Revise','Address it through evidence and explanation.'],['Compare','Save a version and explain the change.'],['Return later','Retrieve after time has passed and verify accuracy.']],challenge:['Which change addresses an overconfident claim about a promise?','Distinguish intention from later conduct and revise the judgment accordingly.','Replace one adjective while keeping the unsupported certainty.','Invent an examiner’s mark as proof of improvement.','A useful revision responds to a specific evidence problem.','Ask what new reasoning the change contributes.'],practice:[['What should diagnose the next edit?','A specific weakness in the response or real feedback.','An invented teacher comment never received.','A random change unrelated to the writing.','Diagnosis needs evidence from the actual response.','diagnosis'],['Why preserve the first submission?','It allows comparison with later reasoning without losing the original.','It guarantees every revision receives full marks.','It prevents the student from learning anything new.','Versions show change without promising attainment.','versions'],['What makes later retrieval distinct?','Attempt a reference after an interval before checking it.','Reread immediately and declare permanent mastery.','Assume confidence establishes exact wording.','Delayed retrieval and source checking test more than immediate familiarity.','recall']],check:[['Which edit strengthens an argument?','Explain how a verified later action supports or qualifies the claim.','Add invented wording that agrees with the thesis.','Increase length without reconsidering evidence.','A revision should improve the claim-evidence relation.','meaning'],['What does the bring-in action preserve?','The original first assessment response remains unchanged.','The assessment is silently overwritten by the workshop draft.','Knowledge scores become an official essay mark.','Copying into an empty draft keeps the source distinct.','workflow'],['Which feedback statement is honest?','Use self-review or teacher feedback actually received.','Every saved paragraph has automatically been specialist marked.','The app guarantees an official examiner’s approval.','Do not replace actual review with invented authority.','review'],['What needs a later opportunity to test?','Accurate retrieval and application after a delay.','Whether clicking Save proves permanent retention.','Whether a completed knowledge check guarantees essay quality.','Completion and durable learning require different evidence.','retention']],writing:'Bring in your first assessment response if available. Identify one weakness using the criteria or real feedback, redraft the relevant section and save a version with a brief explanation of the change.',rubric:['Diagnose a specific weakness using the actual response and real feedback if available.','Strengthen a claim through verified evidence and a clearer explanatory relation.','Compare versions and plan later retrieval without claiming an automatic essay mark.'],extra:{revisionFrom:'lit.carol.workshop-13'}}),
make({topic:'inspector',key:'workshop-01',title:'Act 1 sustained reading and stage directions',scope:'Act 1 · comfort, stage conditions and intrusion',quote:'Teaching lens: the dinner presents a comfortable social arrangement. The Inspector’s arrival and the prescribed change in lighting disturb that arrangement. Read the exact directions and dialogue in your authorised copy.',
cards:[['Read the opening as a staged arrangement','Read the dinner and the Inspector’s arrival in an authorised copy, attending to the directions as well as dialogue. The setting presents social confidence before inquiry changes who controls the conversation. Identify a specific spatial, lighting or conversational choice and explain how it positions characters and audience.'],['Distinguish script from a proposed production','A prescribed lighting change is textual evidence; a modern camera close-up or an invented sound effect is a production possibility. Both can be discussed, but their status differs. Propose a performance choice only after locating what the script requires, and explain why the addition would develop a supported interpretation.'],['Explain the interruption’s structural work','The arrival is more than a new person entering: it redirects the evening from self-congratulation towards scrutiny. Compare who speaks with confidence before and after it. A strong paragraph connects stage conditions, conversational authority and developing knowledge rather than claiming a single lighting effect dictates every audience response.']],details:[['Comfort','Test how the opening arrangement presents social security.'],['Lighting change','Locate the actual direction before discussing an effect.'],['Arrival','Track the shift in conversational purpose and control.']],people:[['Family at dinner','Presents a confident account of its own position.'],['Inspector','Introduces questions that disturb the arrangement.'],['Audience','Can reassess the opening through the developing inquiry.']],movement:[['Read','Follow directions alongside the dinner dialogue.'],['Locate','Identify the arrival and change in stage conditions.'],['Compare','Track whose authority is strengthened or challenged.'],['Propose','Label a production choice and defend it with script evidence.']],challenge:['Which performance argument keeps its evidence honest?','Locate the prescribed lighting change and label any added camera effect as a production choice.','Claim every film close-up is explicitly required by the script.','Ignore all stage directions because only speech can matter.','Script and production can both shape interpretation without being identical.','Check whether the detail comes from the script or your proposed staging.'],practice:[['Why read directions with dialogue?','The staged conditions help shape the exchange and its change.','Directions always supply an official essay mark.','Only costumes can establish meaning in drama.','Dramatic writing includes how a scene is presented.','stagecraft'],['What changes at the arrival?','The evening’s conversational purpose and authority are challenged.','Every character instantly agrees on responsibility.','The play necessarily moves to a different building.','An entrance can redirect action without changing location.','structure'],['Which effect should be qualified?','The changed stage conditions may unsettle an audience’s sense of comfort.','Every viewer must feel exactly the same emotion.','A lighting cue erases all dialogue and action.','A proposed effect needs evidence and room for different responses.','audience']],check:[['What should an opening-stage analysis establish first?','The actual arrangement and directions in the authorised script.','An invented camera sequence treated as a quotation.','An official production identical for all time.','Locate the evidence before inferring its significance.','meaning'],['Which is a directorial addition unless prescribed?','A camera moving into a close-up of a particular face.','A direction actually printed in the play.','A character’s entrance given in the text.','Distinguish a possible production from the written evidence.','performance'],['What makes the entrance structurally significant?','It redirects the conversation towards inquiry and scrutiny.','Every entrance automatically has an identical effect.','It guarantees an immediate resolution of all conflict.','Explain the change in action and authority.','structure'],['What strengthens a paragraph on stagecraft?','Connect a precise direction with a shift in audience knowledge or authority.','List visual details without explaining their function.','Replace the script with a preferred film’s invented words.','Stage evidence needs a relation to a supported interpretation.','argument']],writing:'How does the Act 1 opening prepare for disruption? Analyse one actual stage direction and a change in conversational authority, then propose one clearly labelled performance possibility.',rubric:['Locate exact evidence in an authorised copy without quoting teaching commentary as script.','Connect a stage condition with the dramatic shift in authority or knowledge.','Distinguish prescribed evidence from an optional production and qualify audience effects.']}),
make({topic:'inspector',key:'workshop-02',title:'Act 2 testimony and interrupted dialogue',scope:'Act 2 · claims, challenges and withheld knowledge',quote:'Teaching lens: a character’s account is heard, questioned and interrupted. Sheila’s interventions and the questioning of Mrs Birling change how confident claims can be judged. Track what each speaker knows at that moment.',
cards:[['Map an account before evaluating it','Read the Act 2 exchanges in the full play and note what Gerald or Mrs Birling claims, who hears it and what remains unknown. A reported account may be important evidence without giving direct access to every motive or event. Distinguish what a speaker says from what the play independently establishes.'],['Read interruption as an action','Sheila’s interventions can challenge an explanation or anticipate a consequence before another character sees it. An interruption changes the course or authority of the conversation, but does not automatically prove that the interrupted person is lying. Explain its particular timing and the knowledge behind it.'],['Develop an argument about controlled information','The inquiry orders revelations so that earlier claims can acquire a different significance. Compare a confident statement with the later information that tests it, keeping the sequence clear. Avoid borrowing knowledge from the ending and assuming every character already possesses it in the middle of Act 2.']],details:[['Account','Separate a speaker’s version from independently established information.'],['Interruption','Ask what the intervention changes at this moment.'],['Sequence','Track when the audience and characters acquire crucial knowledge.']],people:[['Speaker giving testimony','Selects an account whose motives require evaluation.'],['Sheila','Intervenes as her understanding develops.'],['Audience','May anticipate implications before some characters recognise them.']],movement:[['Record','Identify a precise claim in the account.'],['Locate','Name what is still unknown at that moment.'],['Challenge','Explain an intervention’s timing and purpose.'],['Reassess','Use later information without moving it backwards in time.']],challenge:['What makes an interruption analytical evidence?','Explain how its timing challenges a claim or redistributes conversational authority.','Assume every interrupted sentence must be a lie.','Treat all later knowledge as already available to every speaker.','An interruption is a dramatic action whose function depends on context.','Identify what changes and who knows enough to challenge it.'],practice:[['Why distinguish testimony from direct confirmation?','A speaker’s account does not reveal every motive as a verified fact.','Everything anyone says must therefore be false.','Accounts cannot contribute any evidence.','Evaluation needs the status and limits of information.','testimony'],['What should analysis of an interruption name?','Its timing, purpose and effect on the exchange.','Only the number of punctuation marks.','A universal rule that interruption proves dishonesty.','The intervention’s function needs a particular situation.','methods'],['What error does a knowledge map prevent?','Giving a character later information before it is revealed.','Reading the acts in their written order.','Considering an audience’s possible anticipation.','Dramatic knowledge changes through sequence.','knowledge']],check:[['What should be recorded when evaluating an account?','What is claimed and what remains unconfirmed.','A guarantee that the speaker’s motive is fully visible.','Only the physical height of the speaker.','Distinguish evidence from certainty about everything behind it.','meaning'],['Which reading is too automatic?','An interrupted speaker must be lying.','An intervention can challenge authority.','The timing can change a statement’s significance.','One feature does not carry the same verdict in every context.','limits'],['How can later revelation affect an earlier claim?','It can require the audience to reassess the earlier confidence.','It proves every character knew the revelation from the start.','It makes sequence irrelevant to drama.','Reassessment differs from retroactively changing knowledge.','structure'],['What supports a sustained argument?','Connect a particular account, intervention and later test of its claim.','List speakers without explaining their relations.','Invent dialogue that removes uncertainty.','A reasoning chain gives the selected moments purpose.','argument']],writing:'How does interrupted testimony control knowledge in Act 2? Track one claim, a particular intervention and later information that tests the claim, using your authorised copy.',rubric:['Distinguish a speaker’s account from information independently established.','Analyse a particular intervention through timing, purpose and knowledge.','Keep the revelation sequence accurate when developing a wider judgment.']}),
make({topic:'inspector',key:'workshop-03',title:'Act 3 revelation and ending workshop',scope:'Act 3 · identity questions and continuing responsibility',quote:'Teaching lens: revelations are followed by debate about the inquiry and the Inspector’s identity. Some characters seek relief in uncertainty; others insist that their conduct still matters. The final telephone call changes the stakes again.',
cards:[['Separate the questions being debated','Read the final act and distinguish questions about the visitor, the reported death and each character’s acknowledged actions. Uncertainty about one does not automatically erase the others. A careful argument names which issue a piece of evidence affects rather than treating every doubt as proof that nothing happened or nobody bears responsibility.'],['Explain relief through contrasting responses','Compare the eagerness to restore normality with Sheila and Eric’s continuing concern about conduct. The disagreement makes an ethical difference visible: reputation or legal uncertainty can be prioritised over learning from acknowledged harm. Support that reading through the exchange, without assuming younger characters are flawless in every respect.'],['Read the ending as renewed pressure','The telephone call repeats an inquiry pattern while altering what the family can expect. It can reopen judgment and unsettle apparent closure. The structure does not provide a single incontestable explanation of the Inspector’s identity, nor allow the reader to ignore the actions discussed merely because the form is puzzling.']],details:[['Identity question','Uncertainty about the visitor has a particular scope.'],['Acknowledged conduct','Actions remain a separate basis for ethical judgment.'],['Telephone call','A renewed inquiry disrupts the attempted return to security.']],people:[['Those seeking relief','Can focus on status, reputation or apparent escape.'],['Sheila and Eric','Continue to question what the family has done.'],['Audience','Must reassess closure without a complete explanation of every uncertainty.']],movement:[['Reveal','Read the final accounts of conduct.'],['Distinguish','Separate identity, death and ethical questions.'],['Compare','Evaluate different responses to apparent escape.'],['Reopen','Explain how the final call changes the stakes.']],challenge:['Which argument preserves the distinction between identity and ethics?','Uncertainty about the visitor does not automatically cancel acknowledged harmful conduct.','If identity is uncertain, all conduct must be morally harmless.','The final call supplies one uncontested explanation of every event.','Questions can overlap without having identical answers or consequences.','Identify which issue the uncertainty actually affects.'],practice:[['What should an ending argument keep separate?','The visitor’s identity and the ethical significance of acknowledged actions.','Every character’s knowledge as if it never changes.','An invented event and a verified script detail as equivalent.','A precise distinction prevents a false cancellation of responsibility.','distinction'],['Why compare reactions to apparent escape?','Different priorities emerge when external consequences seem uncertain.','It proves the younger characters never do anything wrong.','It makes every earlier revelation meaningless.','Responses to relief can expose what has or has not been learned.','character'],['What can the final call do structurally?','Reopen scrutiny and disturb apparent closure.','Guarantee that no further question is possible.','Erase all need to consider conduct.','Repetition can return with changed stakes.','structure']],check:[['Which inference is unsafe?','Doubt about identity proves acknowledged conduct harmless.','Some questions at the ending remain unsettled.','The final call affects expectations.','A factual uncertainty is not an automatic ethical acquittal.','meaning'],['What makes the repeated inquiry pattern significant?','The family faces renewed pressure after seeking relief.','It repeats without any changed context or stakes.','It confirms a single interpretation without qualification.','Structure depends on the relation between repetition and change.','methods'],['Which character judgment is qualified?','Sheila and Eric can recognise responsibility while remaining implicated in harm.','Youth guarantees total innocence throughout the play.','Any admission automatically repairs every consequence.','Recognition and innocence are different claims.','interpretation'],['What develops an argument about the ending?','Explain how uncertainty tests responsibility rather than removing it.','Supply an invented definitive identity and stop analysing.','Treat the puzzle as unrelated to ethical judgment.','Relate dramatic form to the contested responses.','argument']],writing:'How does the ending test whether responsibility depends on external punishment? Compare the family’s responses to uncertainty and analyse the final call without claiming a definitive identity explanation.',rubric:['Separate the visitor’s identity from the significance of acknowledged actions.','Compare contrasting responses without treating recognition as innocence.','Explain renewed inquiry structurally and preserve uncertainty where the script leaves it.']}),
make({topic:'inspector',key:'workshop-04',title:'Mr Birling authority and dramatic irony',scope:'Act 1 · confident forecasts and a knowledge gap',quote:'Teaching lens: Mr Birling speaks confidently about prosperity, the Titanic and the likelihood of war. The play is set in 1912; audiences with later historical knowledge can test the certainty of his predictions.',
cards:[['Identify the actual knowledge gap','In your authorised copy, locate a particular confident forecast and distinguish the character’s 1912 position from later knowledge available to an audience. A discussion of dramatic irony needs that specific difference. Merely calling a statement foolish or surprising does not explain how the drama gives viewers a different basis for judgment.'],['Analyse the performance of certainty','Read how Birling presents his authority through assured prediction and advice. The later audience’s knowledge can unsettle that confidence and encourage scrutiny of his other claims. It does not logically prove that every sentence about business or family must be false; each further claim still needs to be examined.'],['Connect history with dramatic purpose','The 1912 setting allows a later audience to see limits in a self-confident account of progress and security. Explain how that context works through a particular speech. Avoid claiming identical historical knowledge or political views for every viewer, or using a list of dates to replace analysis of authority.']],details:[['Forecast','Identify the exact prediction in the authorised text.'],['Certainty','Examine the verbal performance of expertise.'],['Later knowledge','Name what an audience can recognise differently.']],people:[['Mr Birling','Offers a confident account of the future.'],['Dinner listeners','Receive advice within the evening’s social hierarchy.'],['Historically informed audience','Can judge the forecast against later events.']],movement:[['Locate','Choose one specific forecast.'],['Distinguish','Separate 1912 knowledge from later knowledge.'],['Analyse','Explain how certainty presents authority.'],['Evaluate','Test the wider effect without a universal verdict.']],challenge:['Which account explains dramatic irony precisely?','A specific 1912 forecast conflicts with later historical knowledge available to viewers.','Every confident sentence is ironic simply because it is loud.','One failed prediction proves all possible claims by Birling false.','The effect needs a particular difference in knowledge.','Name what Birling predicts and what a later audience can recognise.'],practice:[['What is needed beyond the label dramatic irony?','A specific knowledge gap and an account of its effect.','Only a surprising tone of voice.','A claim that every audience has identical knowledge.','A label becomes analysis through the relation it identifies.','irony'],['What can failed forecasts invite?','Scrutiny of Birling’s confident authority.','Automatic logical disproof of every sentence he speaks.','Proof that all other characters are perfectly informed.','An invitation to question differs from a universal verdict.','evaluation'],['How should historical context be used?','Explain why a particular forecast is vulnerable to later knowledge.','Append unrelated dates in place of speech analysis.','Assume 1912 characters know every later event.','Context works through the play’s arrangement of knowledge.','context']],check:[['What is the relevant temporal distinction?','The 1912 character position and a later audience’s historical knowledge.','Every character speaks after all future events have occurred.','All viewers lack any knowledge beyond the dinner.','A time gap can shape dramatic judgment.','meaning'],['What should analysis of certainty examine?','How confident advice performs authority in the exchange.','Only whether the speech is long.','An invented quotation from a film treated as script.','Method analysis locates how a claim is presented.','methods'],['Which conclusion exceeds the evidence?','A failed forecast proves every business statement necessarily false.','The audience may question his authority.','The forecast can conflict with later knowledge.','Assess a further claim rather than assuming automatic disproof.','limits'],['Which argument connects form and context?','The historical knowledge gap can destabilise the performance of expertise.','Historical facts remove all need to analyse language.','Every audience must reach an identical political verdict.','Relate context to a supported dramatic function.','argument']],writing:'How does dramatic irony test Mr Birling’s authority? Analyse one precise forecast from your authorised copy, explain the knowledge gap and qualify its wider effect.',rubric:['Identify a particular forecast and the relevant difference in historical knowledge.','Analyse how the speech presents confidence or expertise.','Qualify the judgment without assuming all statements false or all audiences identical.']}),
make({topic:'inspector',key:'workshop-05',title:'Sheila changes and qualified judgments',scope:'Whole play · admission, attention and resistance',quote:'Teaching lens: Sheila acknowledges her part in a dismissal and becomes more alert to the inquiry’s implications. Later she resists treating apparent escape as a reason to forget what the family has done.',
cards:[['Trace change through more than a label','Locate Sheila’s account of the shop dismissal and her responses as questioning develops. A claim that she changes needs evidence of what she acknowledges, whom she listens to and how she acts in later exchanges. Do not turn an early damaging choice into proof that no later recognition can matter.'],['Distinguish recognition from complete repair','Admission is significant, but does not undo the harm or make a character flawless. Explain how her later interventions indicate altered priorities while preserving the limits of what the play shows. A supported account can describe ethical growth without assuming that recognising responsibility automatically repairs every consequence.'],['Use the ending to test the trajectory','Compare her later concern about conduct with attempts to restore normality once the inquiry seems doubtful. This gives the change claim a test under different pressure. Avoid a simple rule that youth guarantees virtue: the argument should depend on particular responses, not age alone or a declaration of permanent perfection.']],details:[['Acknowledgment','Identify what Sheila accepts about her own action.'],['Intervention','Track how her attention changes the exchange.'],['Resistance to forgetting','Test changed priorities when escape appears possible.']],people:[['Earlier Sheila','Uses social power in a damaging decision.'],['Developing Sheila','Acknowledges involvement and questions explanations.'],['Later family debate','Tests whether recognition persists when consequences seem uncertain.']],movement:[['Locate harm','Read the original choice without excusing it.'],['Recognise','Identify admission and growing attention.'],['Test','Compare a later response under changed pressure.'],['Qualify','Distinguish growth from innocence or completed repair.']],challenge:['Which judgment allows ethical change without erasing harm?','Sheila’s later recognition matters while her earlier action remains harmful.','An admission means the harmful action never happened.','Youth automatically makes every choice innocent.','Growth and prior responsibility can be held together.','Keep a change in priorities separate from undoing consequences.'],practice:[['What evidence supports a change claim?','A relation between earlier action and later acknowledgment or response.','Only repeating that she is young.','A fixed label without a particular exchange.','Development needs an explained sequence of conduct.','development'],['What does admission not establish by itself?','Complete repair of harm and permanent perfection.','A willingness to acknowledge involvement.','A possible change in priorities.','Recognition is meaningful without being total restitution.','limits'],['Why compare the ending?','It tests her priorities when apparent escape becomes available.','It proves every earlier action was harmless.','It removes the need for textual evidence.','A trajectory becomes stronger when tested under new pressure.','structure']],check:[['Which distinction is central to her development?','Recognising responsibility differs from being innocent of all harm.','Any recognition proves no damaging choice occurred.','Every later objection makes the original dismissal imaginary.','Keep acknowledgment and the action acknowledged distinct.','meaning'],['What would strengthen analysis of an intervention?','Explain what she challenges and how her knowledge has developed.','Assume every interruption has the same effect.','Count her speeches without considering purpose.','The particular function supports the development claim.','methods'],['Which claim should be rejected?','Age alone guarantees Sheila’s moral superiority in every situation.','Her ending response can show changed priorities.','Her earlier action remains relevant.','Ethical judgment needs conduct rather than a generational shortcut.','interpretation'],['What makes a qualified conclusion?','She shows meaningful recognition, while harm and the limits of repair remain.','She is permanently flawless after one admission.','No change can matter because she once acted badly.','A developmental judgment can avoid both extremes.','argument']],writing:'How far does Sheila’s development demonstrate a changed understanding of responsibility? Analyse an early action, a later intervention and the ending, keeping recognition distinct from repair.',rubric:['Build a developmental claim through precise actions and responses.','Analyse a specific intervention rather than relying on a general change label.','Distinguish recognition, responsibility and repair without using age as automatic proof.']}),
make({topic:'inspector',key:'workshop-06',title:'Gerald testimony and competing interpretations',scope:'Acts 2–3 · assistance, dependency and self-presentation',quote:'Teaching lens: Gerald’s account presents assistance to a vulnerable woman within a relationship of unequal resources. Consider what his account supports, what it leaves uncertain and how later conduct affects its interpretation.',
cards:[['Read the account’s evidential status','Use your authorised copy to locate Gerald’s description of the relationship and the questions or responses around it. Distinguish what he says from direct access to every motive. An account can include assistance without proving that the teller’s self-presentation is complete or that all consequences have been understood.'],['Hold help and unequal power together','Material help can matter while control of accommodation, money and the relationship creates dependency. A reading that calls the conduct entirely generous must address that imbalance; a reading that denies any help must explain the assistance described. Test both through particular details rather than choosing a label before examining the account.'],['Use later conduct as a further test','Compare the earlier account with Gerald’s later attention to the inquiry’s status and the prospect of restoring normality. Explain how that response complicates a claim about responsibility. Do not treat uncertainty as permission to invent a hidden motive, or assume that assistance cancels every ethical question about power.']],details:[['Assistance','Identify what help the account actually describes.'],['Dependency','Consider who controls resources and continuation.'],['Self-presentation','Ask what the teller emphasises and what remains unconfirmed.']],people:[['Gerald as teller','Frames an account of help and relationship.'],['Vulnerable woman','Faces unequal access to security and resources.'],['Critical audience','Tests the account through questions, limits and later conduct.']],movement:[['Locate','Record the assistance described.'],['Question','Identify the power and dependency involved.'],['Compare','Test competing judgments against awkward evidence.'],['Reassess','Read later conduct alongside the earlier account.']],challenge:['Which reading best handles competing evidence?','Assistance can be real while unequal dependency still raises ethical questions.','Any help automatically removes every question of power.','Uncertainty allows the reader to invent motives as proven facts.','A complex judgment should explain both help and inequality.','Do not let one part of the relationship cancel the other.'],practice:[['Why distinguish account from complete motive?','Self-presentation does not independently verify every intention.','Nothing in any testimony can ever be useful.','The audience directly witnesses every past event.','Evaluate what the narrative form allows a viewer to know.','testimony'],['What should a generous-conduct reading address?','The imbalance of resources and control within the relationship.','Only whether Gerald speaks politely.','A guarantee that dependency never matters.','A strong reading deals with evidence that complicates it.','power'],['Why compare his later response?','It provides another test of priorities and responsibility.','It erases all previous assistance automatically.','It supplies unrestricted access to every private thought.','Different moments can qualify an earlier judgment.','structure']],check:[['Which account of the evidence is accurate?','The audience hears a version that needs to be evaluated in context.','Every motive is independently confirmed by direct observation.','The relationship has no material dimension.','Keep an account’s value and its limits visible.','meaning'],['What makes the relationship ethically complex?','Help exists alongside an unequal control of resources.','One kind act proves all power relations equal.','Any inequality means no help can have occurred.','Two aspects can coexist rather than cancel each other.','interpretation'],['Which inference is unsafe?','An unconfirmed hidden motive can be stated as a proven fact.','Later conduct can qualify a reading.','A speaker may frame events selectively.','Uncertainty requires qualification, not invention.','limits'],['What makes a critical comparison fair?','Test each reading against both supporting and awkward details.','Give one reading invented evidence so it loses easily.','Choose a fixed label before opening the play.','A judgment should emerge from an honest evidence test.','argument']],writing:'How should an audience judge Gerald’s account of assistance? Compare two possible readings, address unequal resources and use a later response to refine the judgment.',rubric:['Distinguish testimony from independently established motives.','Account for assistance and dependency together through particular details.','Test competing readings fairly and qualify the final judgment using later conduct.']}),
make({topic:'inspector',key:'workshop-07',title:'Mrs Birling power and responsibility',scope:'Act 2 · charitable authority and unrecognised consequences',quote:'Teaching lens: Mrs Birling describes a refusal of charitable assistance and judges who should bear responsibility. Her confidence is tested by information about a family connection that she has not yet recognised.',
cards:[['Locate authority in an institutional decision','Read Mrs Birling’s account of the appeal and refusal in the authorised play. Her position permits a judgment with material consequences for another person. The existence of a charitable role does not establish that every decision made through it is fair; analyse the grounds she offers rather than treating status as sufficient evidence.'],['Trace what she does not yet know','As she allocates blame, the audience can begin to recognise implications she has not accepted. Keep the sequence precise: a later revelation changes the significance of earlier confidence. Dramatic irony depends on this gap, not simply on a character receiving a surprise or being described as unpleasant.'],['Keep the social judgment proportionate','An institutional setting allows the play to examine how power and prejudice can shape help. It does not prove that all charitable organisations or every individual involved behaves identically. Build an argument from her stated grounds, the refusal’s consequences and her reaction when responsibility comes closer to home.']],details:[['Refusal','Identify the decision and the reasons she gives.'],['Authority','Separate institutional position from fairness of judgment.'],['Unrecognised connection','Track the information that tests confident blame.']],people:[['Mrs Birling','Exercises authority and allocates responsibility.'],['Applicant','Faces the material consequences of refused help.'],['Audience','Can reassess her confidence as connections emerge.']],movement:[['Read','Locate the account of refusal.'],['Evaluate','Examine the grounds rather than trusting status alone.'],['Anticipate','Track what is not yet recognised.'],['Reassess','Relate revelation to the earlier judgment.']],challenge:['Which claim keeps authority and fairness distinct?','A charitable position gives decision-making power but does not prove the refusal just.','Any institutional title guarantees perfect moral judgment.','One refusal proves every charity behaves identically.','A decision’s grounds and consequences still need evaluation.','Judge what is done through the role rather than treating the title as proof.'],practice:[['What should analysis of the refusal examine?','The grounds offered and the consequences for the applicant.','Only the prestige of the institution’s name.','An assumption that power makes judgment infallible.','Authority is a condition of the decision, not its justification.','power'],['What makes the revelation ironic?','It tests blame expressed without recognising a relevant family connection.','All surprising information is automatically the same kind of irony.','Every character already knows everything.','The effect depends on a particular gap in recognition.','irony'],['Which social conclusion is proportionate?','This decision exposes a problem in how institutional power can be used.','Every form of charity is necessarily identical and harmful.','The applicant’s material need never matters.','Scale a general claim to the evidence the play presents.','limits']],check:[['What does Mrs Birling’s role establish?','Power to affect an appeal, not automatic fairness of judgment.','Perfect knowledge of every consequence.','The absence of any material stakes.','A role confers capacity without proving ethical correctness.','meaning'],['Which sequence must an argument preserve?','Confident blame precedes full recognition of the family implication.','Every implication is acknowledged before any refusal is discussed.','Later information is known by every speaker from the outset.','Revelation changes the meaning of earlier confidence.','structure'],['What distinguishes irony from a label of dislike?','A specific difference in knowledge or recognition shapes judgment.','Only a claim that the character is unpleasant.','The number of words in a stage direction.','Explain the dramatic relation rather than substitute an adjective.','methods'],['Which argument is qualified?','The refusal tests how status and prejudice may shape responsibility.','All charities and all members act identically in every situation.','Institutional authority removes the need for evidence.','A social reading needs precision and limits.','argument']],writing:'How does Mrs Birling’s exercise of authority become a test of responsibility? Analyse the refusal’s stated grounds and the later revelation, using the correct sequence of knowledge.',rubric:['Evaluate stated reasons and consequences rather than equating status with fairness.','Explain a specific knowledge gap and preserve the revelation sequence.','Qualify a social judgment without claiming every institution or person identical.']}),
make({topic:'inspector',key:'workshop-08',title:'Eric accountability and family relationships',scope:'Act 3 · individual conduct and conditions around it',quote:'Teaching lens: Eric’s account involves alcohol, sexual exploitation and money taken from the business. Read the full account carefully in an authorised copy. Consider his own responsibility alongside the family relationships and power differences that surround his conduct.',
cards:[['Read responsibility without reducing the seriousness','This workshop concerns sexual exploitation and harmful conduct; you can pause or move to another lesson using the normal navigation. In your authorised copy, distinguish what Eric acknowledges from the family’s reactions. Alcohol and distress form part of the account but do not transfer responsibility for his actions onto the vulnerable woman.'],['Separate context from an excuse','Family relationships can help explain why a person struggles to seek help or communicate honestly. Explanation is not the same as justification. A strong response can consider the conditions around Eric while keeping his decisions, the power imbalance and the harm to another person central to the judgment.'],['Test recognition through later responses','Read Eric’s later concern about responsibility alongside his account, not as a cancellation of it. Contrast the family’s focus on money or reputation with the human consequences under discussion. Avoid turning that contrast into a claim that financial wrongdoing does not matter; ask what is given priority and whose experience receives attention.']],details:[['Acknowledged conduct','Keep the particular acts and their seriousness visible.'],['Family relationships','Consider explanatory conditions without treating them as excuses.'],['Competing priorities','Track attention to money, reputation and human consequences.']],people:[['Eric','Remains accountable while the surrounding conditions are examined.'],['Vulnerable woman','Must not be blamed for another person’s harmful actions.'],['Family','Responds through relationships and competing priorities.']],movement:[['Distinguish','Separate the account from reactions to it.'],['Locate harm','Keep power and consequences in view.'],['Contextualise','Explain family conditions without excusing decisions.'],['Evaluate','Judge later recognition alongside continuing responsibility.']],challenge:['Which judgment maintains accountability?','Family conditions can help explain the situation without excusing Eric’s harmful choices.','Alcohol transfers responsibility to the vulnerable woman.','Acknowledging harm makes the harmful conduct disappear.','Context can matter without cancelling agency or consequences.','Distinguish an explanation from a justification and avoid victim-blaming.'],practice:[['What should family context do in an argument?','Help explain conditions while preserving individual responsibility.','Automatically justify every damaging decision.','Replace the other person’s experience entirely.','A contextual account must retain the conduct it explains.','accountability'],['Why compare reactions about money and harm?','It reveals what different responses prioritise.','It proves financial wrongdoing is morally irrelevant.','It makes reputation the only possible concern.','A contrast can expose priorities without erasing either issue.','methods'],['What does later recognition not establish?','That the earlier harm has been undone.','A possible change in understanding.','A basis for comparing his later response.','Recognition is evidence to assess, not a cancellation of consequences.','limits']],check:[['Which distinction is essential?','Explaining surrounding conditions differs from excusing harmful conduct.','Family difficulty makes all choices automatically justified.','Alcohol means another person bears responsibility for his actions.','Keep context, agency and consequences distinct.','meaning'],['What can contrasting family reactions reveal?','Different priorities about money, reputation and human harm.','That only one issue can ever have moral significance.','That financial wrongdoing necessarily has no consequences.','Priorities can be analysed without denying other concerns.','methods'],['Which claim must be rejected?','The vulnerable woman is responsible for Eric’s harmful choices.','Power differences matter to the relationship.','Later acknowledgment can be examined critically.','Do not displace responsibility onto the person harmed.','accountability'],['What makes a conclusion qualified?','Later recognition matters while responsibility and the limits of repair remain.','An admission guarantees complete repair and permanent innocence.','No surrounding relationship can ever be considered.','A nuanced judgment can include context without erasing harm.','argument']],writing:'How does Priestley present Eric’s accountability within family relationships? Analyse an acknowledgment and contrasting reactions, keeping explanation distinct from excuse and recognising the person harmed.',rubric:['Keep individual responsibility, power differences and the seriousness of harm central.','Use family context to explain conditions without excusing conduct or blaming the person harmed.','Analyse contrasting priorities and qualify claims about recognition and repair.']})
];
